var ENT=[["Great Expectations", "Data validation as testable Python expectations."], ["JSON Schema", "Declarative JSON document validation."], ["Pandera", "Statistical data validation for pandas."], ["Cerberus", "Lightweight Python dict validation."], ["Trifacta", "Visual wrangling suggesting transforms."], ["Talend", "Open-source data integration studio."], ["Pentaho Kettle", "ETL with a visual designer."]];
